using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Threading.Tasks;
using GoogleNas;
class SuiteTests {
 static readonly List<Process> fixtures=new List<Process>();
 static int count;static string rclone,root;static void Check(bool value,string name){count++;if(!value)throw new Exception(name);}
 static async Task<string> Cli(string exe,string[] args,string key=null){using(var p=new Process{StartInfo=new ProcessStartInfo(exe,Core.Args(args)){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,RedirectStandardInput=true}}){if(key!=null)p.StartInfo.EnvironmentVariables["RCLONE_CONFIG_PASS"]=key;p.Start();p.StandardInput.Close();var output=p.StandardOutput.ReadToEndAsync();var error=p.StandardError.ReadToEndAsync();if(!await Task.Run(()=>p.WaitForExit(30000))){p.Kill();throw new Exception("Fixture process timeout");}string text=await output;string err=await error;if(p.ExitCode!=0)throw new Exception("Fixture CLI failed "+p.ExitCode+": "+err);return text;}}
 static int Port(){var l=new TcpListener(IPAddress.Loopback,0);l.Start();int port=((IPEndPoint)l.LocalEndpoint).Port;l.Stop();return port;}
 static async Task Ready(int port){for(int i=0;i<50;i++){try{using(var c=new TcpClient())await c.ConnectAsync(IPAddress.Loopback,port);return;}catch{}await Task.Delay(100);}throw new Exception("Fixture listener unavailable");}
 static async Task<Process> Serve(string type,string path,int port,params string[] options){var args=new List<string>{"serve",type,path,"--addr","127.0.0.1:"+port,"--config","NUL"};args.AddRange(options);var p=Process.Start(new ProcessStartInfo(rclone,Core.Args(args)){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true,RedirectStandardOutput=true});fixtures.Add(p);p.StandardError.ReadToEndAsync();p.StandardOutput.ReadToEndAsync();try{await Ready(port);return p;}catch{if(!p.HasExited)p.Kill();p.Dispose();throw;}}
 static StorageConnection Fixture(string type,string dir){var p=new StorageConnection{Name="Fixture "+type,Provider=type,Path=new[]{"smb","s3","b2","azureblob","azurefiles","gcs"}.Contains(type)?"bucket":"",Letter="Z"};foreach(var f in StorageProviders.Find(type).Fields)p.Options[f.Key]=f.Default;
 foreach(string key in new[]{"host","user","pass","account","key","access_key_id","secret_access_key"})if(p.Options.ContainsKey(key))p.Options[key]=key=="host"?"127.0.0.1":"FixtureOnly!Credential12";
 if(type=="sftp"){p.Options["known_hosts_file"]=Path.Combine(dir,"known_hosts");File.WriteAllText(p.Options["known_hosts_file"],"# configuration-only fixture\n");}
 if(type=="webdav")p.Options["url"]="http://127.0.0.1:1/";
 if(StorageProviders.Find(type).OAuth)p.Options["token"]="{\"access_token\":\"FixtureOnlyToken\",\"token_type\":\"bearer\",\"expiry\":\"2099-01-01T00:00:00Z\"}";
 return p;}
 static async Task MainTests(){Directory.CreateDirectory(root);var engine=new StorageEngine(Path.Combine(root,"store"),rclone);engine.Diagnostics=text=>Console.Error.WriteLine(text);Check(StorageProviders.All.Length==13,"13 providers");
 foreach(var provider in StorageProviders.All){var p=Fixture(provider.Id,root);await engine.Configure(p);string raw=File.ReadAllText(engine.ConfigFor(p));Check(raw.Contains("RCLONE_ENCRYPT_V")&&!raw.Contains("FixtureOnly"),provider.Id+" encrypted at rest");string dump=await Cli(rclone,new[]{"config","dump","--config",engine.ConfigFor(p)},engine.Store.Key);var data=Core.Json.Deserialize<Dictionary<string,Dictionary<string,string>>>(dump)["remote"];Check(data["type"]==provider.Backend,provider.Id+" actual backend configured");if(provider.Id=="ftps")Check(data["explicit_tls"]=="true"&&data["tls"]=="false","FTPS explicit TLS enabled");}
 var stored=Fixture("ftp",root);engine.Store.Put(stored);Check(!File.ReadAllText(Path.Combine(engine.Store.Home,"connections.dat")).Contains("FixtureOnly"),"DPAPI metadata hides credentials");Check(new StorageStore(engine.Store.Home).Load()[0].Get("pass")==stored.Get("pass"),"Credentials survive encrypted reload");var other=Fixture("ftp",root);bool conflict=false;try{engine.Store.Put(other);}catch{conflict=true;}Check(conflict,"Duplicate drive letter rejected");engine.Store.Save(new List<StorageConnection>());Console.WriteLine("13 backend configurations and encrypted storage passed.");
 Check(CapacityInfo.FromQuota(new Dictionary<string,object>{{"total",1024L*1024*1024},{"used",0L},{"free",1024L*1024*1024}}).Contains("1 GB"),"Capacity uses provider quota");Check(CapacityInfo.FromQuota(new Dictionary<string,object>())=="Không cung cấp quota","Missing quota never becomes fake zero capacity");
 string dataDir=Path.Combine(root,"data");Directory.CreateDirectory(dataDir);File.WriteAllText(Path.Combine(dataDir,"fixture.txt"),"Fixture content");
 Process server2=null;int port=Port();using(var server=await Serve("ftp",dataDir,port,"--user","fixture","--pass","FixtureOnly!12")){try{var p=Fixture("ftp",root);p.Options["port"]=port.ToString();p.Options["user"]="fixture";p.Options["pass"]="FixtureOnly!12";await engine.Configure(p);await engine.Test(p);Check(true,"FTP actual loopback login and listing");Console.WriteLine("FTP authenticated listing passed.");}finally{if(!server.HasExited)server.Kill();}}
 string openssl=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"Git","usr","bin","openssl.exe");
 if(File.Exists(openssl)){
  string cert=Path.Combine(root,"fixture.crt"),key=Path.Combine(root,"fixture.key");await Cli(openssl,new[]{"req","-x509","-newkey","rsa:2048","-nodes","-keyout",key,"-out",cert,"-days","1","-subj","/CN=127.0.0.1","-addext","subjectAltName=IP:127.0.0.1"});
  foreach(string mode in new[]{"explicit","implicit"}){port=Port();string fixture=Path.Combine(Path.GetDirectoryName(Path.GetDirectoryName(rclone)),"..","tests","ftps-fixture.py");
   using(var server=Process.Start(new ProcessStartInfo("python",Core.Args(new[]{fixture,port.ToString(),cert,key,mode})){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true})){
    var stdout=server.StandardOutput.ReadToEndAsync();var stderr=server.StandardError.ReadToEndAsync();string prior=Environment.GetEnvironmentVariable("RCLONE_CA_CERT");try{await Ready(port);var p=Fixture("ftps",root);p.Options["port"]=port.ToString();p.Options["user"]="fixture";p.Options["pass"]="FixtureOnly!12";p.Options["tls_mode"]=mode=="implicit"?"Implicit TLS":"Explicit TLS";Environment.SetEnvironmentVariable("RCLONE_CA_CERT",cert);await engine.Configure(p);await engine.Test(p);Check(true,"FTPS real "+mode+" TLS login with certificate validation");Environment.SetEnvironmentVariable("RCLONE_CA_CERT",null);bool rejected=false;try{await engine.Test(p);}catch{rejected=true;}Check(rejected,"FTPS "+mode+" rejects untrusted certificate");Console.WriteLine("FTPS "+mode+" TLS verified; untrusted certificate rejected.");}finally{Environment.SetEnvironmentVariable("RCLONE_CA_CERT",prior);if(!server.HasExited)server.Kill();}
   }
  }
 }
 port=Port();using(var server=await Serve("webdav",dataDir,port,"--user","fixture","--pass","FixtureOnly!12")){try{var p=Fixture("webdav",root);p.Options["url"]="http://127.0.0.1:"+port+"/";p.Options["user"]="fixture";p.Options["pass"]="FixtureOnly!12";await engine.Configure(p);await engine.Test(p);Check(true,"WebDAV actual authenticated listing");Console.WriteLine("WebDAV authenticated listing passed.");string target=Path.Combine(root,"copied.txt");await Cli(rclone,new[]{"copyto","remote:fixture.txt",target,"--config",engine.ConfigFor(p)},engine.Store.Key);Check(File.ReadAllText(target)=="Fixture content","WebDAV real download preserves bytes");
  string letter="ZYXWVUTSRQPONMLKJIHGFED".Select(c=>c.ToString()).FirstOrDefault(c=>!Environment.GetLogicalDrives().Any(d=>d.StartsWith(c+":")));
  if(new Services(engine.Store.Home).WinFspInstalled&&letter!=null){p.Letter=letter;try{await engine.Connect(p);Check(engine.Runtime(p).State=="Đã kết nối","Real WinFsp drive mounted");Check(File.ReadAllText(letter+@":\fixture.txt")=="Fixture content","Mounted drive reads remote content");server.Kill();server.WaitForExit();engine.NetworkChanged();await engine.Poll();await engine.Runtime(p).Job;Check(engine.Runtime(p).State=="Đang nối lại"&&engine.Runtime(p).Service.Running,"Transport loss keeps live VFS and cache instead of killing the mount");using(var resumed=await Serve("webdav",dataDir,port,"--user","fixture","--pass","FixtureOnly!12")){try{engine.NetworkChanged();await engine.Poll();await engine.Runtime(p).Job;Check(engine.Runtime(p).State=="Đã kết nối","Transport recovery reconnects without restarting the VFS");}finally{if(!resumed.HasExited)resumed.Kill();}}server2=await Serve("webdav",dataDir,port,"--user","fixture","--pass","FixtureOnly!12");File.WriteAllText(letter+@":\mounted-write.txt","Mounted write fixture");for(int i=0;i<30&&!File.Exists(Path.Combine(dataDir,"mounted-write.txt"));i++)await Task.Delay(500);Check(File.ReadAllText(Path.Combine(dataDir,"mounted-write.txt"))=="Mounted write fixture","Mounted write uploads to server");}finally{engine.Stop(p).GetAwaiter().GetResult();}Check(!engine.Store.Load().First(x=>x.Id==p.Id).AutoConnect,"Manual pause persists");if(server2!=null){if(!server2.HasExited)server2.Kill();server2.Dispose();server2=null;}}else Console.WriteLine("WinFsp end-to-end mount skipped: driver or free drive letter unavailable.");
 }finally{if(!server.HasExited)server.Kill();}}
 string ssh=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"OpenSSH","ssh-keygen.exe");if(File.Exists(ssh)){
  string host=Path.Combine(root,"host_key"),client=Path.Combine(root,"client_key");await Cli(ssh,new[]{"-q","-t","ed25519","-N","","-f",host});await Cli(ssh,new[]{"-q","-t","ed25519","-N","","-f",client});port=Port();string hosts=Path.Combine(root,"trusted_hosts");File.WriteAllText(hosts,"[127.0.0.1]:"+port+" "+File.ReadAllText(host+".pub"));
  using(var server=await Serve("sftp",dataDir,port,"--user","fixture","--pass","FixtureOnly!12","--key",host,"--authorized-keys",client+".pub")){try{var p=Fixture("sftp",root);p.Options["port"]=port.ToString();p.Options["user"]="fixture";p.Options["pass"]="FixtureOnly!12";p.Options["known_hosts_file"]=hosts;await engine.Configure(p);await engine.Test(p);Check(true,"SFTP password and trusted host key verified");p.Options["pass"]="";p.Options["key_file"]=client;await engine.Configure(p);await engine.Test(p);Check(true,"SFTP SSH private key authentication verified");}finally{if(!server.HasExited)server.Kill();}}
 }
 Directory.CreateDirectory(Path.Combine(dataDir,"bucket"));File.WriteAllText(Path.Combine(dataDir,"bucket","s3.txt"),"S3 fixture");port=Port();using(var server=await Serve("s3",dataDir,port,"--auth-key","fixture,FixtureOnlySecret12")){try{var p=Fixture("s3",root);p.Options["access_key_id"]="fixture";p.Options["secret_access_key"]="FixtureOnlySecret12";p.Options["endpoint"]="http://127.0.0.1:"+port;p.Options["region"]="us-east-1";p.Options["force_path_style"]="true";await engine.Configure(p);await engine.Test(p);Check(true,"S3 signature authentication and bucket listing against real loopback endpoint");}finally{if(!server.HasExited)server.Kill();}}
 Console.WriteLine(count+" suite security, provider configuration, capacity and real protocol tests passed.");
 }
 static int Main(string[] args){try{root=Path.GetFullPath(args[0]);rclone=Path.GetFullPath(args[1]);MainTests().GetAwaiter().GetResult();return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}finally{foreach(var child in fixtures){try{if(!child.HasExited)child.Kill();}catch{}}}}
}
